PROGRAM TimedFeed
VAR
    RUN : BOOL;
    FEED : TON;                 (* 6 s 放料脉冲 *)
    WORK : TON;                 (* 加工计时 *)
    PASS : TON;                 (* 放行计时 *)
    HOLD : BOOL := TRUE;        (* 挡停升起 *)
END_VAR
    (* 启停：启动按钮自锁，停止按钮和急停按钮都是常闭触点（没按时为 TRUE） *)
    RUN := (START OR RUN) AND STOP AND ESTOP;
    LAMP_RUN := RUN;
    C1_FWD := RUN;
    FEED(IN := RUN AND NOT FEED.Q, PT := T#6S);
    E1_RELEASE := FEED.Q;
    (* 零件到工位：加工 3.2 s *)
    WORK(IN := S1 AND HOLD, PT := T#3200MS);
    LAMP_WORK := S1 AND HOLD;
    IF WORK.Q THEN
        HOLD := FALSE;          (* 加工完：落下放行 *)
    END_IF;
    PASS(IN := NOT HOLD, PT := T#1S);
    IF PASS.Q THEN
        HOLD := TRUE;           (* 1 s 后零件已经走过挡板，重新升起 *)
    END_IF;
    ST1_RAISE := HOLD;
END_PROGRAM
